bonuspilot="async()=>{const g=window.__game,p=g.player,l=g.getLevel(),{runThemedBonusJourney}=await import('/tools/themed-bonus-pilot.mjs'),{THEMED_BONUS_COURSES}=await import('/src/levels/themed-bonuses.ts'),course=THEMED_BONUS_COURSES.find(c=>c.parentId==='jungle-terraces'),source=course.data;const report={actions:[],evidence:[],stage:'start'},ctx={p,l,source,course,id:'bonus-jungle-terraces',report,get frame(){return frame;}},pilot=runThemedBonusJourney(ctx),native=p.step.bind(p);let frame=0,advanced=false,last={},next=pilot.next();window.bonusRun={done:false};p.step=(dt,input,level)=>{try{if(advanced){next=pilot.next();advanced=false;}const sample=next.value??{};input.moveX=sample.moveX??0;input.moveY=sample.moveY??0;const n=Math.hypot(input.moveX,input.moveY);if(n>1){input.moveX/=n;input.moveY/=n;}input.moveX=Math.round(input.moveX*100)/100;input.moveY=Math.round(input.moveY*100)/100;for(const held of ['jumpHeld','spinHeld','grindHeld','grabHeld','transferHeld']){input[held]=sample[held]??false;input[held.replace('Held','Pressed')]=sample[held.replace('Held','Pressed')]??(input[held]&&!last[held]);}input.jumpReleased=sample.jumpReleased??(!input.jumpHeld&&!!last.jumpHeld);input.restartPressed=input.jumpCancelled=false;last={...sample};native(dt,input,level);frame++;advanced=true;window.bonusRun.stage=report.stage;if(next.done||p.state==='finished'||p.state==='dead'||frame>12000){window.bonusRun={done:true,frame,state:p.state,crates:p.cratesBroken,deaths:p.totalDeaths,report};p.step=native;input.moveX=input.moveY=0;input.spinHeld=input.spinPressed=input.jumpHeld=input.jumpPressed=input.jumpReleased=false;}}catch(e){window.bonusRun={done:true,error:String(e),frame,state:p.state,crates:p.cratesBroken,report};p.step=native;input.moveX=input.moveY=0;}};}"